var ch = Channel.CreateBounded<Frame>(new BoundedChannelOptions(64) {
    FullMode = BoundedChannelFullMode.Wait,   // backpressure (default)
    SingleReader = true,
});

// producer: awaits while the channel is full
await ch.Writer.WriteAsync(frame, ct);

// consumer: pull, one item at a time
await foreach (var frame in ch.Reader.ReadAllAsync(ct))
    Process(frame);

var options = new ExecutionDataflowBlockOptions {
    BoundedCapacity = 64,             // the bound
    MaxDegreeOfParallelism = 8,       // in-flight work, also a limit
};
var sink = new ActionBlock<Frame>(async f => await ProcessAsync(f), options);
var source = new BufferBlock<Frame>(new DataflowBlockOptions { BoundedCapacity = 64 });

source.LinkTo(sink, new DataflowLinkOptions { PropagateCompletion = true });
await source.SendAsync(frame, ct);    // waits when downstream is saturated
// source.Post(frame) -> false is load shedding, decided deliberately

